"""The dev-environment check advises on setups that drift quietly, without failing."""

from __future__ import annotations

from pathlib import Path
import sys

from scripts import check_dev_environment as env


def test_the_lock_target_comes_from_the_lock_header(tmp_path: Path) -> None:
    lock = tmp_path / "requirements-dev.lock.txt"
    lock.write_text(
        "# This file was autogenerated by uv via the following command:\n"
        "#    uv pip compile pyproject.toml --extra dev --python-version 3.11 -o x.txt\n",
        encoding="utf-8",
    )
    assert env.lock_target(lock) == (3, 11)

    lock.write_text("# no target recorded\nfastapi==1.0\n", encoding="utf-8")
    assert env.lock_target(lock) is None
    assert env.lock_target(tmp_path / "missing.txt") is None

    # The real lock records one; the advisory is useless if this stops parsing.
    assert env.lock_target() is not None


def test_no_virtual_environment_is_an_advisory() -> None:
    advisory = env.virtual_environment_advisory("C:/Python314", "C:/Python314")
    assert advisory is not None and "No virtual environment" in advisory

    assert env.virtual_environment_advisory("C:/repo/.venv", "C:/Python314") is None


def test_an_interpreter_other_than_the_lock_target_is_an_advisory() -> None:
    advisory = env.interpreter_advisory((3, 14), (3, 11))
    assert advisory is not None and "3.14" in advisory and "3.11" in advisory

    assert env.interpreter_advisory((3, 11), (3, 11)) is None
    assert env.interpreter_advisory((3, 14), None) is None


def test_a_package_that_shadows_a_declared_one_is_reported(tmp_path: Path) -> None:
    clean = env.shadowing_advisories(["httpx"], sys.path)
    assert clean == []

    shadow = tmp_path / "httpx"
    shadow.mkdir()
    (shadow / "__init__.py").write_text("", encoding="utf-8")

    advisories = env.shadowing_advisories(["httpx"], [str(tmp_path), *sys.path])

    assert len(advisories) == 1
    assert "`import httpx`" in advisories[0]
    assert str(tmp_path) in advisories[0]


def test_a_bare_directory_with_a_declared_name_does_not_shadow(tmp_path: Path) -> None:
    """A directory without __init__.py is only a namespace portion; the real
    package still wins the lookup, so reporting it would be a false alarm."""

    (tmp_path / "httpx").mkdir()

    assert env.shadowing_advisories(["httpx"], [str(tmp_path), *sys.path]) == []
    assert env.shadowing_advisories(["no-such-distribution-for-cortex"], sys.path) == []


def test_advisories_are_printed_but_never_change_the_exit_code(monkeypatch, capsys) -> None:
    monkeypatch.setattr(env, "virtual_environment_advisory", lambda *_: None)
    monkeypatch.setattr(env, "interpreter_advisory", lambda *_: None)
    monkeypatch.setattr(env, "shadowing_advisories", lambda *_: [])
    quiet_exit = env.main()
    quiet = capsys.readouterr().out
    assert "Advisories" not in quiet

    monkeypatch.undo()
    monkeypatch.setattr(sys, "prefix", sys.base_prefix)
    monkeypatch.setattr(env, "lock_target", lambda *_: (2, 7))
    advised_exit = env.main()
    advised = capsys.readouterr().out

    assert "Advisories (these do not fail the check):" in advised
    assert "No virtual environment is active" in advised
    assert "the CI lock targets 2.7" in advised
    assert advised_exit == quiet_exit
